BL4.EndTransition = function(State_CameraModeState)
 local _paramsSize = 0x8
 local _params = AllocateMemory(_paramsSize);
 if not _params then;print("BL4.EndTransition: Failed To Allocate The Params");return;end;
 -- Clear params struct
 writeBytes(_params, {0,0,0,0,0,0,0,0})
 -- Set inputs: State at +0x0
 writeQword(_params + 0x0, State_CameraModeState)
 UE.CallProcessEventEx(State_CameraModeState, "EndTransition", _params);
 deAlloc(_params);
end
FNR("BL4.EndTransition");

