BL4.PreUpdatePOV = function(OwnerAddress, DeltaTime, State_CameraModeState, InPOV, InViewModelPOV, InBlendDelta, OutPOV, OutViewModelPOV, OutBlendDelta, BlendPct)
 local _paramsSize = 0x2958
